members.products.graphql:
extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key"])

type Query {
  topProducts: [Product!]
}

type Product @key(fields: "id uuid") {
  id: ID!
  name: String!
}

members.reviews.graphql:
extend schema @link(url: "https://specs.apollo.dev/federation/v2.3", import: ["@key"])

type Query {
  latestReviews: [Review!]
}

type Review {
  id: ID!
  body: String!
}

type Product @key(fields: "id") {
  id: ID!
  reviews: [Review!]
}
